#include <stdio.h>
#include <string.h>

#define MOD 1000000007
#define MAX_A 2000
#define MAX_B 2000
#define MAX_SUM 4000

long long fact[2 * MAX_SUM + 5];
long long inv_fact[2 * MAX_SUM + 5];

long long mod_pow(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = res * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return res;
}

void init_fact(int n) {
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = fact[i-1] * i % MOD;
    }
    inv_fact[n] = mod_pow(fact[n], MOD - 2);
    for (int i = n - 1; i >= 0; i--) {
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD;
    }
}

long long comb(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * inv_fact[k] % MOD * inv_fact[n-k] % MOD;
}

int main() {
    init_fact(2 * (MAX_A + MAX_B) + 2);

    int N;
    scanf("%d", &N);

    // dp[a][b] = count of packs with exactly a beef, b peppers
    static int cnt[MAX_A + 1][MAX_B + 1];
    memset(cnt, 0, sizeof(cnt));

    for (int i = 0; i < N; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        cnt[a][b]++;
    }

    // dp2[a][b] = number of ways to reach (a,b) by summing two packs
    static long long dp[MAX_A * 2 + 1][MAX_B * 2 + 1];
    memset(dp, 0, sizeof(dp));

    for (int a = 0; a <= MAX_A; a++) {
        for (int b = 0; b <= MAX_B; b++) {
            dp[a][b] = cnt[a][b];
        }
    }

    // 2D prefix sum to get convolution
    for (int a = 0; a <= 2 * MAX_A; a++) {
        for (int b = 0; b <= 2 * MAX_B; b++) {
            if (a > 0) dp[a][b] = (dp[a][b] + dp[a-1][b]) % MOD;
            if (b > 0) dp[a][b] = (dp[a][b] + dp[a][b-1]) % MOD;
            if (a > 0 && b > 0) dp[a][b] = (dp[a][b] - dp[a-1][b-1] + MOD) % MOD;
        }
    }

    long long ans = 0;
    for (int a = 0; a <= MAX_A; a++) {
        for (int b = 0; b <= MAX_B; b++) {
            if (cnt[a][b] == 0) continue;
            // sum over all j with (a + a_j, b + b_j)
            long long total_ways = dp[a + MAX_A][b + MAX_B]; // max offset safe
            // subtract the pack with itself
            total_ways = (total_ways - comb(a + b + a + b, a + a) + MOD) % MOD;
            // multiply by count of current pack
            ans = (ans + total_ways * cnt[a][b]) % MOD;
        }
    }

    // each pair counted twice (i,j) and (j,i)
    ans = ans * ((MOD + 1) / 2) % MOD;

    printf("%lld\n", ans);

    return 0;
}

#include <stdio.h>
