#define MOD 1000000007LL

typedef long long ll;

typedef struct {
    int a, b;
} Pack;

int cmp_pack(const void *p1, const void *p2) {
    const Pack *x = (const Pack *)p1;
    const Pack *y = (const Pack *)p2;
    if (x->a != y->a) return x->a - y->a;
    return x->b - y->b;
}

ll mod_pow(ll a, ll e) {
    ll r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Pack *packs = (Pack *)malloc(sizeof(Pack) * N);
    int maxs = 0;

    for (int i = 0; i < N; i++) {
        scanf("%d %d", &packs[i].a, &packs[i].b);
        int s = packs[i].a + packs[i].b;
        if (s > maxs) maxs = s;
    }

    /* factorials up to 2*max(a+b) */
    int LIM = 2 * maxs;
    ll *fact = (ll *)malloc(sizeof(ll) * (LIM + 1));
    ll *invfact = (ll *)malloc(sizeof(ll) * (LIM + 1));

    fact[0] = 1;
    for (int i = 1; i <= LIM; i++) fact[i] = fact[i - 1] * i % MOD;
    invfact[LIM] = mod_pow(fact[LIM], MOD - 2);
    for (int i = LIM; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

    qsort(packs, N, sizeof(Pack), cmp_pack);

    ll ans = 0;
    ll same = 0; /* subtract pairs of identical packs */

    int i = 0;
    while (i < N) {
        int j = i;
        while (j < N && packs[j].a == packs[i].a && packs[j].b == packs[i].b) j++;

        int a = packs[i].a, b = packs[i].b;
        int cnt = j - i;

        /* number of arrangements using two identical packs:
           (2a+2b)! / ((2a)! (2b)!) */
        ll ways_same = fact[2 * a + 2 * b];
        ways_same = ways_same * invfact[2 * a] % MOD;
        ways_same = ways_same * invfact[2 * b] % MOD;

        ll pairs = (ll)cnt * (cnt - 1) / 2 % MOD;
        same = (same + pairs * ways_same) % MOD;

        i = j;
    }

    /* Total over ordered choice with replacement, then divide by 2:
       Sum over all i,j of C((ai+bi)+(aj+bj), ai+aj)
     */
    for (int x = 0; x < N; x++) {
        for (int y = 0; y < N; y++) {
            int A = packs[x].a + packs[y].a;
            int B = packs[x].b + packs[y].b;
            ll ways = fact[A + B];
            ways = ways * invfact[A] % MOD;
            ways = ways * invfact[B] % MOD;
            ans += ways;
            if (ans >= MOD) ans -= MOD;
        }
    }

    /* remove i=j and duplicate orderings */
    ans = (ans - same) % MOD;
    if (ans < 0) ans += MOD;

    ll inv2 = (MOD + 1) / 2;
    ans = ans * inv2 % MOD;

    printf("%lld\n", ans);

    free(packs);
    free(fact);
    free(invfact);
    return 0;
}

