public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();

        // cnt[a][b]: number of packs with a beef pieces and b peppers
        // From the original constraints, a,b are in [1,100]
        long[][] cnt = new long[101][101];

        for (int i = 0; i < N; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            cnt[a][b]++;
        }

        // Precompute factorials up to 200
        long[] fact = new long[201];
        long[] invFact = new long[201];
        fact[0] = 1;
        for (int i = 1; i <= 200; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[200] = modPow(fact[200], MOD - 2);
        for (int i = 200; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

        long ans = 0;

        for (int a1 = 1; a1 <= 100; a1++) {
            for (int b1 = 1; b1 <= 100; b1++) {
                if (cnt[a1][b1] == 0) continue;

                for (int a2 = a1; a2 <= 100; a2++) {
                    int bStart = (a2 == a1 ? b1 : 1);
                    for (int b2 = bStart; b2 <= 100; b2++) {
                        if (cnt[a2][b2] == 0) continue;

                        long waysChoose;
                        if (a1 == a2 && b1 == b2) {
                            if (cnt[a1][b1] < 2) continue;
                            waysChoose = cnt[a1][b1] * (cnt[a1][b1] - 1) / 2 % MOD;
                        } else {
                            waysChoose = cnt[a1][b1] * cnt[a2][b2] % MOD;
                        }

                        int A = a1 + a2;
                        int B = b1 + b2;

                        // Number of ways to divide A beef and B peppers into two skewers
                        // and order ingredients on each skewer, considering skewers unlabeled:
                        // If the two original packs are different, skewers are distinguishable by contents.
                        // Total arrangements after combining:
                        // C(A+B, A) * C(2,1) ? No.
                        //
                        // Correct count:
                        // Choose which ingredients go to first skewer and second skewer preserving totals
                        // from the two packs only by final arrangement on two skewers:
                        // This equals:
                        // (A+B)! / (A! B!) * A! * B! = (A+B)! ? No.
                        //
                        // The intended count for two skewers each containing some sequence of beef/pepper,
                        // using all A beef and B peppers, where skewers are an unordered pair, is:
                        // sum over x=0..A, y=0..B of
                        // [number of sequences on skewer1 with x beef, y pepper] *
                        // [number on skewer2 with A-x beef, B-y pepper]
                        // divided by 2 when both skewers identical.
                        //
                        // This simplifies to:
                        // sum C(x+y, x) * C(A+B-x-y, A-x), with unordered correction.
                        //
                        // However, for this problem's known formula, the number of arrangements
                        // for two chosen packs (a1,b1),(a2,b2) is:
                        // C(a1+b1, a1) * C(a2+b2, a2) if treated separately,
                        // and doubled when packs differ because swapping skewers matters as set? No.
                        //
                        // Distinct arrangements are determined by the set of two skewers and internal orders.
                        // Since combining two chosen packs does not constrain original ingredients,
                        // each final skewer meal corresponds to partitioning beef/peppers counts between skewers.
                        //
                        // We compute directly by enumeration over count split.
                        long arr = 0;
                        for (int x = 0; x <= A; x++) {
                            for (int y = 0; y <= B; y++) {
                                long s1 = comb(x + y, x, fact, invFact);
                                long s2 = comb((A - x) + (B - y), A - x, fact, invFact);
                                long add = s1 * s2 % MOD;

                                if (x == A - x && y == B - y) {
                                    // identical skewers, count once
                                    arr = (arr + add) % MOD;
                                } else if (x > A - x || (x == A - x && y > B - y)) {
                                    // count each unordered pair once
                                    arr = (arr + add) % MOD;
                                }
                            }
                        }

                        ans = (ans + waysChoose * arr) % MOD;
                    }
                }
            }
        }

        System.out.println(ans % MOD);
    }

    static long comb(int n, int r, long[] fact, long[] invFact) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

