static const long long MOD = 1000000007LL;

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> A(N), B(N);
    int maxS = 0;
    for (int i = 0; i < N; i++) {
        cin >> A[i] >> B[i];
        maxS = max(maxS, A[i] + B[i]);
    }

    // Need factorials up to max(Ai+Aj+Bi+Bj) <= 2*maxS
    int LIM = 2 * maxS;
    vector<long long> fact(LIM + 1), invfact(LIM + 1);
    fact[0] = 1;
    for (int i = 1; i <= LIM; i++) fact[i] = fact[i - 1] * i % MOD;
    invfact[LIM] = modpow(fact[LIM], MOD - 2);
    for (int i = LIM; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

    auto C = [&](int n, int k) -> long long {
        if (k < 0 || k > n) return 0;
        return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD;
    };

    long long ans = 0;

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            int meat = A[i] + A[j];
            int pepper = B[i] + B[j];

            // Number of ways to split all meat/pepper onto two distinct skewers,
            // allowing either skewer to have any number of each ingredient:
            // For a skewer with x meat and y pepper, arrangements on that skewer:
            // C(x+y, x)
            // Summing over all splits:
            // sum_{xm=0..meat} sum_{xp=0..pepper}
            //   C(xm+xp, xm) * C((meat-xm)+(pepper-xp), meat-xm)
            //
            // By Vandermonde-type identity this equals:
            // C(meat+pepper+2, meat+1) - 2? No.
            // Direct combinational simplification:
            // Number of ways to place separators among all ingredients of two types
            // on two ordered skewers = C(meat+pepper+2, meat+1) ??? not correct.
            //
            // Safer: use identity
            // sum_{xp} C(xm+xp, xm) * C((meat-xm)+(pepper-xp), meat-xm)
            // = C(meat+pepper+1, meat)
            // independent of xm
            // then summing xm gives (meat+1)*C(meat+pepper+1, meat)
            // similarly equals (pepper+1)*C(meat+pepper+1, pepper)
            //
            // Since problem statement counts arrangements distinct if set of skewers
            // differs OR order on skewers differs, skewers are distinguished.
            long long ways = (long long)(meat + 1) * C(meat + pepper + 1, meat) % MOD;
            ans += ways;
            if (ans >= MOD) ans -= MOD;
        }
    }

    cout << ans % MOD << '\n';
    return 0;
}

