    long long ans = 0;
    for (int i = 0; i < n; i++)
        for (int j = i+1; j < n; j++) {
            long long B = b[i]+b[j], G = g[i]+g[j], tot = B+G;
            ans = (ans + C(tot, B) % MOD * ((tot+1) % MOD)) % MOD;
        }
    cout << ans << endl;
}
